fn solve(x: i8) -> u8 {
    // Normalize the input angle to the range [0, 360)
    let normalized_angle = ((x % 360 + 360) % 360) as u32;

    let mut min_deviation = 180; // Maximum possible deviation
    let mut best_rotation = 0;

    for r in 0..4 {
        // Calculate the resulting angle after r quarter-turns
        let resulting_angle = (normalized_angle + 90 * r) % 360;

        // Calculate the deviation from vertical
        let deviation = resulting_angle.min(360 - resulting_angle);

        // Update the best rotation if we found a smaller deviation
        if deviation < min_deviation {
            min_deviation = deviation;
            best_rotation = r;
        }
    }

    best_rotation
}